<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { api, apiUrl, apiBlob, accessToken } from '../lib/api.js'
import PageHeader from '../components/PageHeader.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { conversationTitle, isFixedGroup } from '../../../utils/chatGroups.js'

const rows=ref([]),total=ref(0),page=ref(1),query=ref(''),type=ref(''),status=ref(''),loading=ref(false)
const selected=ref(''),detail=ref(null),messagePage=ref(1),messageQuery=ref(''),kind=ref(''),messageStatus=ref(''),sender=ref(''),from=ref(''),to=ref(''),reading=ref(false)
const error=ref(''),notice=ref(''),action=ref(null),reason=ref(''),saving=ref(false),preview=ref(null),opening=ref(false)
const ownerAction=ref(null),nextOwnerId=ref('')
let blobUrl=''
let alive=true,listVersion=0,detailVersion=0,ownerToken=accessToken()
function closePreview(){if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl='';preview.value=null}
function clearPrivate(){closePreview();rows.value=[];detail.value=null;preview.value=null;selected.value='';action.value=null;reason.value='';ownerAction.value=null;nextOwnerId.value=''}
function current(token){const ok=alive&&token===accessToken()&&token===ownerToken;if(!ok&&alive)clearPrivate();return ok}
function failure(e,token){if(current(token)){error.value=e.message;if([401,403].includes(e.status)){clearPrivate();listVersion++;detailVersion++}}}
const time=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
const size=n=>n>=1024**3?(n/1024**3).toFixed(2)+' GB':n>=1024**2?(n/1024**2).toFixed(1)+' MB':Math.ceil(n/1024)+' KB'
const labels={active:'正常',paused:'已停用',dissolved:'已解散',visible:'正常显示',hidden:'已隐藏',text:'文字',image:'图片',file:'文件',sticker:'表情包'}
function schoolLabel(group){return ({college:'学院群',department:'学院群',major:'专业群',class:'班级群'})[group?.kind]||'学籍群'}
function memberRole(member){return ({owner:'群主',admin:'管理员',member:'群成员'})[member.role]||'群成员'}
function ownerCandidates(){if(detail.value?.conversation?.status==='dissolved')return [];return (detail.value?.conversation?.members||[]).filter(p=>p.current&&p.status==='active'&&p.schoolIdentityVerified===true)}
function prepareOwner(){const c=detail.value?.conversation;if(!c||c.type!=='group'||c.status==='dissolved'||saving.value||reading.value||!current(ownerToken))return;closePreview();action.value=null;ownerAction.value={cid:c.id,title:conversationTitle(c),ownerId:c.ownerId||'',revision:c.groupRevision||0};nextOwnerId.value=c.ownerId||'';error.value='';notice.value=''}
async function setOwner(){const a=ownerAction.value,token=ownerToken,target=nextOwnerId.value;if(!a||saving.value||!current(token)||selected.value!==a.cid||target===a.ownerId)return;if(!ownerCandidates().some(p=>p.id===target)){error.value='请选择当前活跃且已实名的群成员';return}saving.value=true;error.value='';try{await api('/admin/chat/conversations/'+a.cid+'/owner',{method:'PUT',body:{ownerId:target,revision:a.revision}});if(!current(token)||selected.value!==a.cid)return;ownerAction.value=null;nextOwnerId.value='';await Promise.all([load(),read()]);if(current(token)&&selected.value===a.cid)notice.value='群主已更新，群主可在前台设置和撤销管理员。'}catch(e){failure(e,token);if(current(token)&&e.status===409&&selected.value===a.cid){ownerAction.value=null;nextOwnerId.value='';await read();if(current(token))error.value=e.message+'，请重新选择群主。'}}finally{if(current(token))saving.value=false}}
async function load(){const token=ownerToken,v=++listVersion;loading.value=true;error.value='';try{const r=await api('/admin/chat/conversations?'+new URLSearchParams({query:query.value,type:type.value,status:status.value,page:page.value}));if(!current(token)||v!==listVersion)return;rows.value=r.items;total.value=r.total}catch(e){failure(e,token)}finally{if(current(token)&&v===listVersion)loading.value=false}}
function search(){page.value=1;selected.value='';detail.value=null;preview.value=null;ownerAction.value=null;nextOwnerId.value='';action.value=null;detailVersion++;load()}
async function read(){const token=ownerToken,cid=selected.value,v=++detailVersion;if(!cid)return;reading.value=true;error.value='';closePreview();try{const r=await api('/admin/chat/conversations/'+cid+'/messages?'+new URLSearchParams({query:messageQuery.value,kind:kind.value,status:messageStatus.value,senderId:sender.value,from:from.value,to:to.value,page:messagePage.value}));if(!current(token)||v!==detailVersion||cid!==selected.value)return;detail.value=r}catch(e){if(v===detailVersion)failure(e,token)}finally{if(current(token)&&v===detailVersion)reading.value=false}}
function select(c){selected.value=c.id;detail.value=null;preview.value=null;ownerAction.value=null;nextOwnerId.value='';action.value=null;messagePage.value=1;messageQuery.value='';kind.value='';messageStatus.value='';sender.value='';from.value='';to.value='';read()}
function searchMessages(){messagePage.value=1;read()}
function prepare(m){if(!m&&detail.value?.conversation?.status==='dissolved'){error.value='群聊已由群主解散，不能重新启用';return}closePreview();ownerAction.value=null;nextOwnerId.value='';const c=detail.value.conversation;action.value={cid:c.id,mid:m?.id||'',revision:m?m.revision:c.revision,status:m?(m.status==='hidden'?'visible':'hidden'):(c.status==='paused'?'active':'paused')};reason.value='';notice.value=''}
async function moderate(){const a=action.value,token=ownerToken;if(!a||saving.value||!current(token))return;saving.value=true;error.value='';try{await api('/admin/chat/conversations/'+a.cid+(a.mid?'/messages/'+a.mid:''),{method:'PATCH',body:{status:a.status,reason:reason.value,revision:a.revision}});if(!current(token))return;action.value=null;notice.value='处理已生效，原始记录已保留';await Promise.all([load(),read()])}catch(e){failure(e,token)}finally{if(current(token))saving.value=false}}
async function attachment(m){const a=m.attachment,token=ownerToken,cid=selected.value,v=detailVersion;if(!a||opening.value||!current(token))return;opening.value=true;try{const r=await api('/admin/chat/files/'+a.id+'/ticket',{method:'POST',body:{}});if(!current(token)||cid!==selected.value||v!==detailVersion||action.value||ownerAction.value)return;const url=apiUrl(r.url);if(m.kind==='image')preview.value={url,name:a.name};else {const link=document.createElement('a');link.href=url;link.rel='noreferrer';link.download=a.name;document.body.appendChild(link);link.click();link.remove()}}catch(e){failure(e,token)}finally{if(current(token))opening.value=false}}
async function sticker(m){const token=ownerToken,cid=selected.value,v=detailVersion;if(!current(token)||opening.value)return;opening.value=true;try{const blob=await apiBlob('/admin/chat/stickers/'+m.sticker.id+'/content');if(!current(token)||cid!==selected.value||v!==detailVersion||action.value||ownerAction.value)return;closePreview();blobUrl=URL.createObjectURL(blob);preview.value={url:blobUrl,name:m.sticker.name}}catch(e){failure(e,token)}finally{if(current(token))opening.value=false}}
function expired(){listVersion++;detailVersion++;clearPrivate()}
onMounted(()=>{window.addEventListener('hufe:auth-expired',expired);load()})
onBeforeUnmount(()=>{alive=false;listVersion++;detailVersion++;clearPrivate();window.removeEventListener('hufe:auth-expired',expired)})
</script>

<template>
  <div class="chat-admin">
    <PageHeader title="对话管理" description="查看全部私聊、群聊与原始消息；处理违规内容，保留记录和操作依据。"/>
    <div class="oversight-notice"><span class="oversight-icon">管</span><div><strong>仅全局管理员可访问</strong><p>查看、附件读取与处理操作均留痕。消息按最新在前显示，历史消息可翻页查看；请仅为平台管理需要访问记录。</p></div><RouterLink :to="{name:'audit'}">查看审计日志 ›</RouterLink></div>
    <p v-if="error" class="oversight-error" role="alert">{{ error }}</p><p v-if="notice" class="oversight-success" role="status">{{ notice }}</p>
    <form class="oversight-filters" @submit.prevent="search"><label class="oversight-search">搜索会话 / 消息<input v-model="query" placeholder="姓名、账号、群名、消息内容或文件名" maxlength="100"/></label><label>会话类型<select v-model="type"><option value="">全部类型</option><option value="direct">一对一私聊</option><option value="group">群聊</option></select></label><label>会话状态<select v-model="status"><option value="">全部状态</option><option value="active">正常</option><option value="paused">已停用</option><option value="dissolved">已解散</option></select></label><button class="button button-primary" :disabled="loading">查询</button><button type="button" class="button button-secondary" @click="query='';type='';status='';search()">重置</button></form>
    <div class="oversight-layout">
      <section class="oversight-list"><header><h2>全部会话 <small>{{ total }}</small></h2><button class="button button-ghost" :disabled="loading" @click="load">刷新</button></header><p v-if="loading" class="oversight-empty">正在加载…</p><p v-else-if="!rows.length" class="oversight-empty">暂无符合条件的会话<br/><small>用户发起私聊或群聊后，会显示在这里。</small></p>
        <button v-for="c in rows" :key="c.id" type="button" class="oversight-row" :class="{selected:selected===c.id}" @click="select(c)"><div class="oversight-row-title"><span class="oversight-kind">{{ c.type==='group'?'群':'私' }}</span><strong>{{ conversationTitle(c) }}</strong><span v-if="c.schoolGroup" class="oversight-tag">固定群</span><span v-if="c.status==='paused'||c.status==='dissolved'" class="oversight-tag danger">{{ c.status==='dissolved'?'已解散':'停用' }}</span></div><p>{{ c.lastMessage || '尚无消息' }}</p><footer><span>{{ c.messageCount }} 条消息 · {{ c.members.filter(m=>m.current).length }} 位成员</span><time>{{ time(c.updatedAt) }}</time></footer></button>
        <div class="oversight-pager"><button class="button button-secondary" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</span><button class="button button-secondary" :disabled="page*20>=total||loading" @click="page++;load()">下一页</button></div>
      </section>
      <section class="oversight-detail"><div v-if="!selected" class="oversight-placeholder"><span>信</span><h2>选择一段会话</h2><p>从左侧打开会话，查看成员、完整消息和处理记录。</p></div><p v-else-if="reading&&!detail" class="oversight-empty">正在读取消息记录…</p>
        <template v-else-if="detail"><header class="oversight-detail-head"><div><span class="oversight-tag">{{ detail.conversation.type==='group'?'群聊':'一对一私聊' }} · {{ labels[detail.conversation.status] }}</span><h2>{{ conversationTitle(detail.conversation) }}</h2><p>{{ detail.conversation.messageCount }} 条消息 · {{ detail.conversation.hiddenCount }} 条已隐藏</p></div><div class="oversight-head-actions"><button v-if="detail.conversation.type==='group'&&detail.conversation.status!=='dissolved'" class="button button-primary" :disabled="reading||saving" @click="prepareOwner">指定群主</button><button class="button button-secondary" :disabled="reading" @click="read">刷新记录</button><button v-if="detail.conversation.status!=='dissolved'" class="button" :class="detail.conversation.status==='paused'?'button-primary':'button-danger'" :disabled="reading||saving" @click="prepare(null)">{{ detail.conversation.status==='paused'?'恢复会话':'停用会话' }}</button></div></header>
          <p v-if="detail.conversation.status==='paused'" class="oversight-paused">该会话已停用：禁止发消息、上传附件及修改群成员；历史记录仍保留。系统固定群不可自行退出；自建群普通成员仍可退出。</p>
          <p v-if="detail.conversation.status==='dissolved'" class="oversight-paused">此自建群已由群主解散，不可恢复。全部成员仅可查看历史记录，不能发送新消息或管理群聊；后台仍可核查和处理历史消息。</p>
          <p v-else-if="!isFixedGroup(detail.conversation)&&detail.conversation.type==='group'" class="oversight-school">自建群：普通成员可自行退出；群主可在前台明确确认后解散。</p>
          <p v-if="detail.conversation.schoolGroup" class="oversight-school">{{ schoolLabel(detail.conversation.schoolGroup) }} · 系统固定群，依据已核验学籍自动关联成员，不可自行退出或解散；后台可指定群主，群主可设置管理员。</p>
          <details class="oversight-members"><summary>成员与历史发言人（{{ detail.conversation.members.length }}）</summary><div v-for="p in detail.conversation.members" :key="p.id"><strong>{{ p.name }}</strong><span>{{ p.username || '—' }} · {{ p.department || '学院未提供' }}</span><small>{{ memberRole(p) }} · {{ p.current?'当前成员':'已离开' }}{{ p.status==='active'?'':' · 账号非正常状态' }}</small></div></details>
          <form class="oversight-message-filters" @submit.prevent="searchMessages"><input v-model="messageQuery" aria-label="搜索消息" placeholder="搜索消息内容、文件名或发言人" maxlength="100"/><select v-model="sender" aria-label="发言人"><option value="">全部发言人</option><option v-for="p in detail.conversation.members" :key="p.id" :value="p.id">{{ p.name }}（{{ p.username }}）</option></select><select v-model="kind" aria-label="消息类型"><option value="">全部消息类型</option><option v-for="k in ['text','image','file','sticker']" :key="k" :value="k">{{ labels[k] }}</option></select><select v-model="messageStatus" aria-label="消息状态"><option value="">全部可见状态</option><option value="visible">正常显示</option><option value="hidden">已隐藏</option></select><label>开始日期<input v-model="from" type="date"/></label><label>结束日期<input v-model="to" type="date"/></label><button class="button button-primary" :disabled="reading">筛选记录</button></form>
          <p class="oversight-count">共 {{ detail.total }} 条匹配记录 · {{ reading?'正在刷新…':'最新消息在前' }}</p>
          <div class="oversight-messages"><p v-if="!detail.items.length" class="oversight-empty">暂无符合条件的消息</p><article v-for="m in detail.items" :key="m.id" class="oversight-message" :class="{'is-hidden':m.status==='hidden'}"><header><span class="oversight-avatar">{{ m.sender.name.slice(-2) }}</span><div><strong>{{ m.sender.name }}</strong><small>{{ m.sender.username }} · {{ time(m.createdAt) }} · #{{ m.seq }}</small></div><span class="oversight-tag" :class="{danger:m.status==='hidden'}">{{ labels[m.status] }}</span></header><p v-if="m.kind==='text'" class="oversight-text">{{ m.text }}</p><button v-else-if="m.attachment" class="oversight-attachment" :disabled="opening" @click="attachment(m)"><span>{{ labels[m.kind] }}</span><div><strong>{{ m.attachment.name }}</strong><small>{{ size(m.attachment.size) }} · {{ m.kind==='image'?'点击查看图片':'点击下载文件' }}</small></div><b>↗</b></button><button v-else-if="m.kind==='sticker'&&m.sticker" class="oversight-attachment" :disabled="opening" @click="sticker(m)">[表情包] {{ m.sticker.name }} · 点击查看</button><p v-if="m.status==='hidden'" class="oversight-hidden-hint">前台已隐藏；以上为仅管理员可见的原始记录。</p>
            <details class="oversight-trace"><summary>来源与处理信息</summary><dl><dt>消息编号</dt><dd>{{ m.id }}</dd><dt>发送账号</dt><dd>{{ m.sender.id }}</dd><dt>来源 IP</dt><dd>{{ m.trace?.ip || '历史消息未记录' }}</dd><dt>IP 归属地</dt><dd>{{ m.trace?.location?.label || '无法确定' }}（非精确定位）</dd><dt>设备</dt><dd>{{ m.trace?.device ? [m.trace.device.os,m.trace.device.browser,m.trace.device.type].join(' · ') : '历史消息未记录' }}</dd><dt>请求编号</dt><dd>{{ m.trace?.requestId || '历史未记录' }}</dd><dt>最近处理</dt><dd>{{ m.moderation ? m.moderation.actor.name+' · '+time(m.moderation.createdAt)+' · '+m.moderation.reason : '无' }}</dd></dl></details>
            <footer><RouterLink class="button button-ghost" :to="{name:'audit',query:{targetId:m.id}}">操作追溯</RouterLink><button class="button button-secondary" :disabled="reading||saving" @click="prepare(m)">{{ m.status==='hidden'?'恢复显示':'隐藏消息' }}</button></footer></article></div>
          <div class="oversight-pager"><button class="button button-secondary" :disabled="messagePage<=1||reading" @click="messagePage--;read()">上一页</button><span>{{ messagePage }} / {{ Math.max(1,Math.ceil(detail.total/30)) }}</span><button class="button button-secondary" :disabled="messagePage*30>=detail.total||reading" @click="messagePage++;read()">下一页</button></div>
          <details class="oversight-history"><summary>最近处理记录（{{ detail.history.length }}）</summary><p v-if="!detail.history.length">暂未进行管理操作</p><div v-for="h in detail.history" :key="h.id"><strong>{{ h.messageId?'消息':'会话' }}：{{ labels[h.previous] }} → {{ labels[h.status] }}</strong><p>{{ h.reason }}</p><small>{{ h.actor.name }} · {{ time(h.createdAt) }}</small></div></details>
        </template>
      </section>
    </div>
    <ConfirmDialog :open="!!ownerAction" title="指定群主" description="群主可在前台设置、撤销群管理员并管理群成员。确认后立即生效，并保留操作记录。" confirm-text="确认指定群主" tone="primary" :busy="saving" :confirm-disabled="!nextOwnerId||nextOwnerId===ownerAction?.ownerId||!ownerCandidates().some(p=>p.id===nextOwnerId)" @cancel="ownerAction=null;nextOwnerId=''" @confirm="setOwner"><p>{{ ownerAction?.title }}</p><label class="oversight-owner-label">选择当前活跃的实名群成员<select v-model="nextOwnerId" :disabled="saving"><option value="">请选择群主</option><option v-for="p in ownerCandidates()" :key="p.id" :value="p.id">{{ p.name }}（{{ p.username || p.department || '群成员' }}）{{ p.id===ownerAction?.ownerId?' · 当前群主':'' }}</option></select></label><p v-if="!ownerCandidates().length" class="oversight-error">暂无可指定的活跃实名群成员。</p><p v-if="error" class="oversight-error">{{ error }}</p></ConfirmDialog>
    <ConfirmDialog :open="!!action" :title="action?.mid?(action.status==='hidden'?'隐藏这条消息':'恢复消息显示'):(action?.status==='paused'?'停用会话':'恢复会话')" description="操作将立即生效并记录处理人和原因。原始消息不会删除。" confirm-text="确认处理" :busy="saving" :confirm-disabled="reason.trim().length<2" @cancel="action=null" @confirm="moderate"><label class="oversight-reason">处理原因（必填）<textarea v-model="reason" maxlength="500" rows="4" placeholder="请填写具体原因，2至500字"/></label><p v-if="error" class="oversight-error">{{ error }}</p></ConfirmDialog>
    <ConfirmDialog :open="!!preview" :title="preview?.name||'图片记录'" description="原始聊天图片，仅供管理核查。" confirm-text="关闭预览" tone="primary" @cancel="closePreview" @confirm="closePreview"><img v-if="preview" :src="preview.url" alt="聊天图片原件" class="oversight-preview" referrerpolicy="no-referrer" @error="error='图片读取失败或链接已过期，请重新打开';closePreview()"/></ConfirmDialog>
  </div>
</template>

